// Captures what the Admin club write routes put on the wire and leave in the database, by running the real Admin
// Route Handlers (apps/admin/src/app/api) and the real @rotra/db services (Prisma) against a throwaway local
// Postgres. The harness is capture-writes-base.mjs; the Go side is apps/api/internal/writetest. Groups:
//   ranking    POST /api/ranking-settings
//   licenses   POST /api/clubs/{clubId}/licenses
//   clubname   PATCH /api/clubs/{clubId}            (the name change review)
//   clubs      POST /api/clubs                      (Add club)
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55441:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55441/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-clubs.test.mjs [-t ranking]
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it.
// The cases are generated by gen-writes-admin-clubs-cases.py. Output: apps/api/internal/adminwrites/testdata/<group>.golden.json.
//
// Two things are replaced, and only these:
//   verifySubject   answers the step's subject (a step with none is signed out), so loadAccountContext (the
//                   active-admin check) and every service run for real;
//   supabaseProviderAdmin().createLogin   the club login. There is no Supabase here, and unmocked it throws, so
//                   every Add club would stop at a staged club and a 503. The mock answers a subject that is a pure
//                   function of the operation ref (the club id), which is what the real provider does for a retry
//                   (it finds the login its operation made). The Go side has no provider: it makes the sign-in
//                   identity (auth_identities) in the same transaction, so `auth_provider` and `auth_subject` of
//                   club_accounts cannot match and are not in the shared snapshot (see clubs.cases.json).
import { createHash } from 'node:crypto'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'

vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'supabase', subject } : null
  },
}))

vi.mock('../../../../packages/db/src/auth/supabase-provider-admin.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  supabaseProviderAdmin: () => ({
    async createLogin({ operationRef }) {
      const h = createHash('sha256').update(`login:${operationRef}`).digest('hex')
      return { subject: `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-8${h.slice(17, 20)}-${h.slice(20, 32)}` }
    },
    async readLogin() {
      return null
    },
    async updateLogin() {},
  }),
}))

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/adminwrites/testdata')
const apiDir = resolve(root, 'apps/admin/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
})
afterAll(async () => {
  await capture?.close()
})

for (const name of ['ranking', 'licenses', 'clubname', 'clubs']) {
  test(name, async () => {
    await captureWrites({ db: capture.db, testdata, name, apiDir })
  })
}
